static BOOL parent_background(HWND w){HDC dc=CreateCompatibleDC(NULL);BITMAPINFO info={0};void *pixels=NULL;info.bmiHeader.biSize=sizeof(info.bmiHeader);info.bmiHeader.biWidth=180;info.bmiHeader.biHeight=-30;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;HBITMAP bitmap=dc?CreateDIBSection(dc,&info,DIB_RGB_COLORS,&pixels,NULL,0):NULL;HGDIOBJ old=bitmap?SelectObject(dc,bitmap):NULL;if(!old){if(bitmap)DeleteObject(bitmap);if(dc)DeleteDC(dc);return FALSE;}SendMessageW(w,WM_PRINTCLIENT,(WPARAM)dc,PRF_CLIENT|PRF_ERASEBKGND);GdiFlush();COLORREF pixel=GetPixel(dc,170,15);SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);return pixel==RGB(42,123,56);}
